L4_1.m_Crash = 30
L4_1.m_Talk_KOREA = "후우! 좋아, 다리도 팔도 가벼워. 오늘 컨디션 최고야!"
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "ふう！　よし、身体も軽いし、今日は絶好調だよ！"
L4_1.m_Talk_ENG = "Whew! I feel light today. I’m in the best condition!"
L4_1.m_Talk_TWN = "呼！很好，手腳都很輕盈，今天的狀態非常好！"
L4_1.m_Talk_THA = "ว้าว! วันนี้ฉันรู้สึกเบา ฉันอยู่ในสภาพที่ดีที่สุด!"
L4_1.m_Talk_VTN = "Ye! Hôm nay tôi cảm thấy người thật nhẹ nhàng. Tôi đang ở trong tình trạng tốt nhất!"
L4_1.m_Talk_SCN = "呼！很好，身轻如燕。今天的状态非常棒！"
L4_1.m_Talk_DEU = "Puh! Sehr gut, meine Glieder sind leicht. Ich bin in Topform!"
L4_1.m_Talk_FRA = "Pfiou ! Je me sens si légère aujourd'hui ! Je suis en pleine forme !"
