L11_1.m_Talk_KOREA = "기운이 넘치는 게 아니라 띨띨한 거겠지."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "元気いっぱいなんじゃなく、ただアホなだけだろう。"
L11_1.m_Talk_ENG = "That’s not being energetic; that’s being stupid."
L11_1.m_Talk_TWN = "那不是鬥志高昂，是不知死活吧？"
L11_1.m_Talk_THA = "นั่นไม่ใช่ความกระตือรือร้น นั่นมันโง่มาก"
L11_1.m_Talk_VTN = "Đó không phải là năng lượng; đó là ngu ngốc."
L11_1.m_Talk_SCN = "不是充满干劲，而是脑子笨吧。"
L11_1.m_Talk_DEU = "Sie ist nicht voller Elan, sondern lernt nicht dazu."
L11_1.m_Talk_FRA = "Ce n'est pas de l'énergie, c'est de la stupidité."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "COUNTERCASE_INGRID_NORMAL_1@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 30921
