L12_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L12_1.m_Pos = "R"
L12_1.m_Talk_KOREA = "불만 보면 뛰어드는 불나방도 아니고. 귀찮아 죽겠어."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "飛んで火に入る夏の虫じゃあるまいし……面倒でしかない。"
L12_1.m_Talk_ENG = "She’s like a moth to a flame. This is so bothersome."
L12_1.m_Talk_TWN = "她是飛蛾嗎？一天到晚撲火，煩死了。"
L12_1.m_Talk_THA = "เธอเป็นเหมือนแมลงเม่าที่ลุกเป็นไฟ นี่มันน่ารำคาญมาก"
L12_1.m_Talk_VTN = "Cô ấy cứ như một con thiêu thân lao vào ngọn lửa. Thật khó chịu."
L12_1.m_Talk_SCN = "只是在飞蛾扑火而已。真是烦死人了。"
L12_1.m_Talk_DEU = "Sie ist wie eine Motte, die ins Feuer springt. Total nervig."
L12_1.m_Talk_FRA = "Elle agit comme un papillon de nuit attiré par la lumière. C'est ridicule."
