L15_1.m_Talk_JPN = "まだやる気なら早くかかってこい、この石頭。"
L15_1.m_Talk_ENG = "Let’s finish this quick, knucklehead."
L15_1.m_Talk_TWN = "不要拖拖拉拉的，快點出手吧，傻瓜。"
L15_1.m_Talk_THA = "มาจบเรื่องนี้กันเร็ว ๆ นะหัวกะโหลก"
