L16_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L16_1.m_Pos = "C"
L16_1.m_Talk_KOREA = "단, 내가 상대해 주는 조건은 잊지 않았겠지?"
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "ただし、妾が相手をしてやる条件を忘れてないだろうな？"
L16_1.m_Talk_ENG = "You haven’t forgotten the bet, have you?"
L16_1.m_Talk_TWN = "但你沒忘記我答應和你對決的條件吧？"
L16_1.m_Talk_THA = "คุณยังไม่ลืมเดิมพันใช่ไหม?"
L16_1.m_Talk_VTN = "Vẫn chưa quên vụ cá cược chứ?"
L16_1.m_Talk_SCN = "不过，可别忘了我们的赌注哦？"
L16_1.m_Talk_DEU = "Aber vergiss nicht die Kondition dafür, dass ich deine Herausforderung annehme."
L16_1.m_Talk_FRA = "Tu n'as pas oublié notre pari ?"
L17_1 = {}
