L21_1.m_Talk_KOREA = "괜찮아! 이기면 되지, 이기면!"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "平気よ！　勝てばいいんでしょ、勝てば！"
L21_1.m_Talk_ENG = "It’s okay! I will win!"
L21_1.m_Talk_TWN = "OK！反正贏就好啦！"
L21_1.m_Talk_THA = "ใช่! ฉันจะชนะ!"
L21_1.m_Talk_VTN = "Không sao đâu! Tôi sẽ thắng!"
L21_1.m_Talk_SCN = "没问题！只要赢了就好，我会赢的！"
L21_1.m_Talk_DEU = "Kein Ding! Dann gewinne ich halt!"
L21_1.m_Talk_FRA = "Ça va aller ! Je finirai par gagner !"
