L23_1.m_Face = "UNIT_IDLE"
L23_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L23_1.m_Pos = "C"
L23_1.m_Talk_KOREA = "흥. 보통 도박중독자들이 따서 꼭 갚겠다고 하던데."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "ふん。よくギャンブル狂いどもが「勝ったら必ず返す」と言っていたが。"
L23_1.m_Talk_ENG = "Hmpf. You sound like a compulsive gambler."
L23_1.m_Talk_TWN = "哼，你這就是賭徒心態。"
L23_1.m_Talk_THA = "หืม.. คุณดูเหมือนนักพนันที่ชอบท้าทาย"
L23_1.m_Talk_VTN = "Hừm. Cô có vẻ nghiện cờ bạc."
L23_1.m_Talk_SCN = "哼。通常赌徒们都会这么说。"
L23_1.m_Talk_DEU = "Hmpf. Spielsüchtige sagen ja immer, dass sie gewinnen und auf jeden Fall ihre Schulden zurückzahlen werden."
L23_1.m_Talk_FRA = "Hmpf. Dit comme ça, on croirait entendre une joueuse compulsive."
L24_1 = {}
L24_1.m_CutScenKey_Talk = "COUNTERCASE_INGRID_NORMAL_1@24#Talk"
L24_1.m_CutScenProcessKey = 24
