L24_1.m_Pos = "C"
L24_1.m_Talk_KOREA = "물론 네 승률이 도박보다도 낮다는 건 알고 있지?"
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "汝は己の勝率がギャンブル以下であることを、承知のうえで言っているんだな？"
L24_1.m_Talk_ENG = "You do know that your odds are lower than at a casino, right?"
L24_1.m_Talk_TWN = "不過你知道你的勝率比賭博的賠率還低吧？"
L24_1.m_Talk_THA = "คุณรู้ไหมว่าอัตราต่อรองของคุณต่ำกว่าที่คาสิโน ว่าไหม?"
L24_1.m_Talk_VTN = "Có biết rằng tỷ lệ cược của cô thấp hơn ở sòng bạc, phải không?"
L24_1.m_Talk_SCN = "你知道现在的胜率比赌博都要低吧？"
L24_1.m_Talk_DEU = "Dir ist klar, dass deine Gewinnchancen niedriger sind als beim Glücksspiel?"
L24_1.m_Talk_FRA = "Tu sais que tes chances de gagner sont aussi faibles qu'au casino ?"
