L35_1 = "아무리 빨라 봤자, 그 허우적거리는 공격에 누가 맞아 주겠어?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "たとえ速度があっても、そんなやみくもな攻撃では容易に躱されてしまうぞ？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I mean, what’s the point of being fast if you can’t hit anything?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "就算你的速度很快，但揮得毫無章法，哪個傻瓜會被你打到？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ฉันหมายถึงจะมีประโยชน์อะไรถ้าตีอะไรไม่ได้?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Ý tôi là, nhanh để làm gì nếu không thể đánh trúng thứ gì?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "就算再快，以你那虚浮的攻击，还想命中我？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Du kannst so schnell sein, wie du willst, aber von deinen unbeholfenen Angriffen lässt sich keiner treffen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "À quoi bon être rapide si tu ne peux même pas me toucher ?"
L34_1.m_Talk_FRA = L35_1
