L17_1 = "으으! 아깝다!! 겨우 종이 한 장의 차이였는데!"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "うう、くやしい！！　紙一重の差だったのに！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Oh, bummer! I almost had you this time!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "可惡！真可惜！！就差那麼一點！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "โอ้เจ้าผู้เกียจคร้าน! คราวนี้ฉันเกือบจะได้คุณแล้ว!"
L16_1.m_Talk_THA = L17_1
L17_1 = "Ôi, chết tiệt! Lần này tôi suýt nữa đã thắng!"
L16_1.m_Talk_VTN = L17_1
L17_1 = "呃呃！真可惜！！就剩下薄薄一张纸的差距而已！"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Urgh! Wie schade!!! Es ging um eine Haaresbreite!"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Oh non ! Quel dommage ! J'y étais presque, pourtant !"
L16_1.m_Talk_FRA = L17_1
