L18_1 = "LAURA_STREGA_EVENT_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "R"
L18_1 = "너희 나라 종이는 꽤 두껍나 봐? 함선 재료로 써도 되겠어."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "汝の故郷の紙はずいぶん分厚いみたいだな？\n艦船の材料に使えるかもな。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Your idea of “almost” must be very different from everyone else's."
L17_1.m_Talk_ENG = L18_1
L18_1 = "差不只一點吧？應該是天差地遠。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ความคิดของคุณที่ว่า “เกือบ” จะต้องแตกต่างจากความคิดของคนอื่นๆ มาก"
L17_1.m_Talk_THA = L18_1
L18_1 = "Khái niệm về “suýt” của cô hẳn phải rất khác với những người khác."
L17_1.m_Talk_VTN = L18_1
L18_1 = "你的纸也太厚了吧？都能当作舰船材料了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Haare sind in eurem Land wohl sehr breit? Breit genug, dass sie als Material für Schiffe dienen könnten?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "On dirait que nous n'avons pas la même définition du mot « presque » ..."
L17_1.m_Talk_FRA = L18_1
