L21_1 = "COUNTERCASE_INGRID_NORMAL_1@70#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 30921
L20_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
