L20_1.m_Pos = "C"
L21_1 = "아까 내 낫에서 뿜어져 나온 그 빛은 뭐야? "
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "さっき私の鎌から放たれた光は何だったの？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "What was that light that my scythe emitted?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "剛剛從我的鐮刀發射出來的光是怎麼回事？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "แสงที่เคียวของฉันปล่อยออกมาคืออะไร?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Ánh sáng mà lưỡi hái của tôi phát ra là gì?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "刚才我的镰刀上发出的光是什么？ "
L20_1.m_Talk_SCN = L21_1
L21_1 = "Was war dieses Licht, das vorhin aus meiner Sense schien?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Qu'est-ce que c'était que cette lumière qui émanait de ma faux ? "
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "COUNTERCASE_INGRID_NORMAL_1@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 30921
L21_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "지금까지 한 번도 그런 적 없었는데… 어째선지 그 빛을 본 다음 기억이 몽롱해."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "今まで一度もあんなことなかったのに……理由はわからないけど、\nあの光を見た後の記憶が曖昧で。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "That never happened before... I don’t remember anything afterwards."
L21_1.m_Talk_ENG = L22_1
L22_1 = "之前都不會這樣欸…不知道為什麼，看到光之後的事都想不太起來。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "นั่นไม่เคยเกิดขึ้นมาก่อน... หลังจากนั้นฉันก็จำอะไรไม่ได้เลย"
L21_1.m_Talk_THA = L22_1
L22_1 = "Điều đó chưa từng xảy ra trước đây... Tôi không nhớ bất cứ điều gì sau đó."
L21_1.m_Talk_VTN = L22_1
L22_1 = "至今为止从未出现过的光芒……但我之后的记忆就开始有些朦胧了。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Das ist noch nie passiert ... Und alles nach diesem Licht in vage in meiner Erinnerung."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Ça n'est jamais arrivé avant... J'ai vu la lumière et puis tout est devenu flou..."
L21_1.m_Talk_FRA = L22_1
