L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "헛소리하는 거 보니까, 아직도 정신이 오락가락 하나 봐?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "その様子だと、まだ目が覚めていないようだな。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "The shock of losing must have hit you hard."
L28_1.m_Talk_ENG = L29_1
L29_1 = "你是還沒清醒是吧？怎麼說些我聽不懂的話。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ความตกใจของการสูญเสียคงกระทบคุณอย่างหนัก"
L28_1.m_Talk_THA = L29_1
L29_1 = "Cú sốc thua cuộc chắc hẳn đã tác động mạnh đến cô."
L28_1.m_Talk_VTN = L29_1
L29_1 = "看你胡言乱语的样子，应该是精神不太好吧？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Du bist wohl noch durch den Wind, wenn du Unsinn redest?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "On dirait que tu n'as pas encore retrouvé tes esprits."
L28_1.m_Talk_FRA = L29_1
