L29_1.m_Talk_THA = L30_1
L30_1 = "Nhân tiện, cô không quên mình phải xếp hàng tồn kho đấy chứ?"
L29_1.m_Talk_VTN = L30_1
L30_1 = "不过，你该没忘记打赌整理库存的事情吧？"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Und vergiss lieber nicht, dass du das Inventar halten musst."
