L37_1 = "에이, 뭘. 나중에 더블 민트 프라페나 같이 먹으러 가자."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "気にしないで。後で一緒にダブルミントフラッペでも食べに行こうね。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "You’re welcome. Let’s go have a Double Mint Frappe when we have the time."
L36_1.m_Talk_ENG = L37_1
L37_1 = "客氣什麼，下次我們一起去喝雙倍薄荷冰沙。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ด้วยความยินดี. ไปดื่มดับเบิ้ลมิ้นต์เฟรปเป้ กันดีกว่าเมื่อเรามีเวลา"
L36_1.m_Talk_THA = L37_1
L37_1 = "Không có gì. Hãy đi uống Double Mint Frappe khi rảnh nhé."
L36_1.m_Talk_VTN = L37_1
L37_1 = "唉，别客气。下次我们一起去吃薄荷冰沙吧。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ach, kein Ding. Gehen wir das nächste Mal zusammen einen Doppel-Minz-Frappé trinken."
