L44_1 = "하긴, 라우라가 오늘따라 심하게 굴긴 했어."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "たしかに今日のラウラは容赦なかったもんね。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Yeah, Laura went a bit too far today."
L43_1.m_Talk_ENG = L44_1
L44_1 = "也是，蘿拉這次真的下手滿狠的。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ใช่ วันนี้ลอร่าไปไกลไปหน่อย"
L43_1.m_Talk_THA = L44_1
L44_1 = "Đúng, hôm nay Laura đã làm hơi quá."
L43_1.m_Talk_VTN = L44_1
L44_1 = "也是，劳拉今天下手确实有点重。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ja, Laura war heute echt etwas zu schroff."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Eh bien, Laura n'y est pas allée de main morte aujourd'hui."
L43_1.m_Talk_FRA = L44_1
