L45_1 = "자세가 무너진 잉그리드를 넘어트린 다음…!!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "バランスを崩したイングリッドを倒した後……！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "She made you trip when lost your balance, and then..."
L44_1.m_Talk_ENG = L45_1
L45_1 = "她打趴重心不穩的英格麗後…！！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เธอทำให้คุณสะดุดเมื่อเสียสมดุล และจากนั้น..."
L44_1.m_Talk_THA = L45_1
L45_1 = "Cô ấy khiến cô vấp ngã khi mất thăng bằng, và sau đó..."
L44_1.m_Talk_VTN = L45_1
L45_1 = "在英格丽失去平衡摔倒后……！！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Zuerst hat sie dich umgeworfen, als du aus der Balance gekommen bist ..."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Elle t'a fait tomber quand tu as perdu l'équilibre et puis...!"
L44_1.m_Talk_FRA = L45_1
