L2_1 = "자세가 자꾸 무너지는 게 문제라면, 요가 같은 걸 배워보는 건 어때?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "姿勢を崩すことが問題なら、ヨガとかやってみたらどうかな？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "If you’re having trouble keeping your balance, how about learning Yoga?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "你老是重心不穩的話，要不要去學的瑜珈啊？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "หากคุณมีปัญหาในการรักษาสมดุล ลองเรียนโยคะดูไหม?"
L1_1.m_Talk_THA = L2_1
L2_1 = "Nếu gặp khó khăn trong việc giữ thăng bằng, hay là học Yoga?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "如果姿势不对，总是失去平衡的话，去学习下瑜伽怎么样？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Vieleicht solltest du Yoga lernen, wenn du Probleme mit der Balance hast?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Si tu as du mal à rester sur tes pieds, peut-être que tu devrais te mettre au yoga."
L1_1.m_Talk_FRA = L2_1
