L5_1 = "몸의 전체적인 밸런스를 잡아줘서 예쁘고 균형 잡힌 몸매를 만들어 준대."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "身体のバランスを整えて、美しいボディラインを作れるんだって。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "They say Yoga helps improve your balance and keeps your body in shape!"
L4_1.m_Talk_ENG = L5_1
L5_1 = "聽說瑜珈可以訓練核心肌群，保持身體平衡。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ว่ากันว่าโยคะช่วยเพิ่มความสมดุลและช่วยให้ร่างกายของคุณมีรูปร่างที่ดี!"
L4_1.m_Talk_THA = L5_1
L5_1 = "Người ta nói Yoga giúp cải thiện khả năng giữ thăng bằng và giữ dáng cho cơ thể!"
L4_1.m_Talk_VTN = L5_1
L5_1 = "听说可以增加身体整体的平衡性，锻炼出美丽又均衡的身材。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Yoga soll die deine Körperbalance verbessern und deine Haltung in Einklang bringen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "On dit que c'est un sport qui aide à garder l'équilibre et à sculpter le corps."
L4_1.m_Talk_FRA = L5_1
