L17_1.m_Pos = "L"
L18_1 = "…균형에 대한 조언. 그것이 그대가 나를 찾은 이유란 말이지."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "……つまり、均衡についての助言が欲しい。それで私のところへ来たということか。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "You came to me seeking advice regarding balance?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "…你想得到有關平衡的建議，所以才來找我的是嗎？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "คุณมาหาฉันเพื่อขอคำแนะนำเกี่ยวกับความสมดุลใช่ไหม?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Cô đến gặp tôi để xin lời khuyên về sự cân bằng?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "……对平衡的建议，这就是你来找我的理由吗？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "... Einen Tipp über den Einklang? Deshalb hast du mich aufgesucht?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "...Tu es donc venue jusqu'à moi pour que je te donne des conseils sur comment garder l'équilibre ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
