L19_1 = "그래! 난 네가 숨은 고수라는 걸 한 눈에 알아봤거든."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "そうよ！　私は君が隠れた達人だってこと、とっくの前から気づいてたから。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Yes! I know that you’re a great martial artist."
L18_1.m_Talk_ENG = L19_1
L19_1 = "沒錯！我一眼就看出你是深藏不露的高手。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ใช่! ฉันรู้ว่าคุณเป็นนักสู้ที่ยอดเยี่ยม"
L18_1.m_Talk_THA = L19_1
L19_1 = "Đúng! Tôi biết cậu là một võ sĩ giỏi."
L18_1.m_Talk_VTN = L19_1
L19_1 = "是啊！我早就知道你是隐藏的高手。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Genau! Ich habe sofort erkannt, dass du ein versteckter Meister bist."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Oui ! J'ai tout de suite deviné que tu étais un maître des arts martiaux !"
L18_1.m_Talk_FRA = L19_1
