L21_1.m_Face = "UNIT_IDLE"
L21_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "카페에 출퇴근할 때마다, 항상 여기서 너를 봤어."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "カフェに通勤するたびに、いつもここであなたを見たわ。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "I see you every day on my way to work."
L21_1.m_Talk_ENG = L22_1
L22_1 = "我去咖啡廳上班時，常常在這裡看到你。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เจอกันทุกวันตอนไปทำงาน"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tôi gặp cậu mỗi ngày trên đường đi làm."
L21_1.m_Talk_VTN = L22_1
L22_1 = "我每次在咖啡店上下班时，都能在这里见到你。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ich habe dich immer hier gesehen, wenn ich im Café zur Arbeit kam und wieder ging."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Je te vois tous les jours sur le chemin pour aller au café."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "COUNTERCASE_INGRID_NORMAL_1@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 30921
L22_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L22_1.m_Pos = "C"
L22_1.m_Crash = 30
L23_1 = "아침부터 저녁까지 한 발로 서있는 건… 분명, 무언가 대단한 수행을 하고 있는 거지?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "朝から晩まで片足立ちをしてるってことは……\nきっと、なにかすごい修行をしてるんだよね？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "You’re always standing here on one leg... I know you’re training for something greater!"
L22_1.m_Talk_ENG = L23_1
L23_1 = "從早到晚都維持金雞獨立的姿勢…想必是在進行什麼偉大的修行吧？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "คุณยืนขาเดียวอยู่ตรงนี้เสมอ... ฉันรู้ว่าคุณกำลังฝึกฝนเพื่อสิ่งที่ยิ่งใหญ่กว่า!"
L22_1.m_Talk_THA = L23_1
L23_1 = "Cậu luôn đứng bằng một chân ở đây... Tôi biết cậu đang luyện tập cho việc gì đó vĩ đại!"
L22_1.m_Talk_VTN = L23_1
L23_1 = "从早到晚，坚持用一只脚站立……说明你在进行非常了不起的修行，没错吧？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Du stehst von morgens bis abends auf einem Bein ... du führst bestimmt ein spezielles Training aus!"
L22_1.m_Talk_DEU = L23_1
L23_1 = "J'ai vu que tu te tenais toujours là sur une seule jambe, du matin au soir... Tu t'entraînes pour quelque chose de grandiose, n'est-ce pas ?"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
