L23_1.m_fTalkTime = 0.03
L24_1 = "ふっ！　君はなかなかの慧眼の持ち主と見た。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Hah, you’re a wise girl."
L23_1.m_Talk_ENG = L24_1
L24_1 = "呵！真是好眼力。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ฮ่า คุณเป็นผู้หญิงที่ฉลาด"
L23_1.m_Talk_THA = L24_1
L24_1 = "Hah, cô là một cô gái thông minh."
L23_1.m_Talk_VTN = L24_1
L24_1 = "呼！你果然很有眼光。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Hmpf! Du hast einen feinen Sinn."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Hé ! Tu es plutôt futée."
