L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "L"
L27_1 = "그렇다. 나는 늘 그대와 같은 자를 기다리고 있었다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "そうだ。私は長い間、君のような者が訪れるのを待っていた。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "That is correct. I’ve been standing here, waiting for someone like you."
L26_1.m_Talk_ENG = L27_1
L27_1 = "沒錯！你就是我在等的人。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ถูกต้อง ฉันยืนอยู่ที่นี่ รอคนเหมือนคุณ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Đúng rồi. Tôi đã đứng đây, chờ đợi một người như cô đấy."
L26_1.m_Talk_VTN = L27_1
L27_1 = "是的。我一直在等像你这样的人。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Du hast recht. Ich habe stets auf jemanden wie dich gewartet."
L26_1.m_Talk_DEU = L27_1
L27_1 = "C'est exact. J'attendais la venue d'un être tel que toi."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "COUNTERCASE_INGRID_NORMAL_1@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 30921
L27_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "CHOI_ALPHA_NULL_SHORT"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "L"
L28_1 = "이 부동검법을 진가를 알아볼 자를……."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "この『不動剣法』の真価を知る者を……！"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Someone who will recognize my Stationary Swordsmanship."
L27_1.m_Talk_ENG = L28_1
L28_1 = "我一直在等待明白不朽劍法真諦的人出……"
L27_1.m_Talk_TWN = L28_1
L28_1 = "คนที่จะจำวิชาดาบที่อยู่กับที่ของฉันได้"
L27_1.m_Talk_THA = L28_1
L28_1 = "Ai đó sẽ công nhận Kiếm Thuật Bất Động của tôi."
L27_1.m_Talk_VTN = L28_1
L28_1 = "能看出不动剑法真谛的人……"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Auf jenen, der meine Stillstand-Schwertkunst erkennen würde ..."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Quelqu'un qui saurait reconnaître la grandeur de ma technique d'épée stationnaire...."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "COUNTERCASE_INGRID_NORMAL_1@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 30921
L28_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L28_1.m_Pos = "R"
L28_1.m_Crash = 30
L29_1 = "거, 검법? 그 자세가 사실 검법이었다고?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "け、剣法？　その姿勢って剣法のひとつだったの？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "S-swordsmanship? That was part of your swordsmanship?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "劍法？那個姿勢是劍法？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "วิชาดาบ? นั่นเป็นส่วนหนึ่งของวิชาดาบของคุณเหรอ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "S-kiếm thuật? Đó là một phần kiếm thuật của cậu sao?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "剑、剑法？那个姿势是剑法？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Eine Sch-Schwertkunst? Deine Haltung war in Wahrheit eine Schwertkunst?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "T...technique d'épée ? Cette posture, c'est une technique d'épée ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
