L31_1 = "COUNTERCASE_INGRID_NORMAL_1@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 30921
L30_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_IDLE"
L31_1 = "CHOI_ALPHA_NULL_SHORT"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "설명하지. 이 자세는 천, 지, 인. 부동검법 삼단세 중 가장 중요한 자세."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "説明しよう。この姿勢は天・地・人、不動剣法の要となる上段の構え。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Let me explain. There are three major postures in my Swordsmanship; Heaven, Earth, and Man."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我這就跟你解釋解釋。這個姿勢代表天、地、人。而不朽劍法三段式中最重要的姿勢就是，"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เดี๋ยวฉันอธิบายให้ฟัง ทักษะดาบของฉันมีท่าทางหลักอยู่สามท่า สวรรค์ โลก และมนุษย์"
L30_1.m_Talk_THA = L31_1
L31_1 = "Hãy để tôi giải thích. Có ba tư thế chính trong Kiếm thuật của tôi; Trời, Đất và Con Người."
L30_1.m_Talk_VTN = L31_1
L31_1 = "其实那个姿势是天、地、人，不动剑法三段中，最重要的姿势。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich erkläre es dir. Diese Haltung ist die wichtigste aus den dreien der Schwertkunst – Himmel, Erde und Mensch."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Laisse-moi t'expliquer. Ma technique comporte trois postures majeures ; le Ciel, la Terre et l'Homme."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "COUNTERCASE_INGRID_NORMAL_1@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 30921
L31_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "UNIT_PRIDE"
L31_1.m_Face = L32_1
L32_1 = "CHOI_ALPHA_NULL_SHORT"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L31_1.m_Crash = 40
L32_1 = "……<color=#ffd34c>인의 자세</color>다!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "……<color=#ffd34c>人の姿勢</color>である！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "... And this is the most important of all, the <color=#ffd34c>Posture of Man</color>!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "……<color=#ffd34c>人的姿勢</color>！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "... และนี่คือสิ่งที่สำคัญที่สุด <color=#ffd34c>ท่าทางของมนุษย์</color>!"
L31_1.m_Talk_THA = L32_1
L32_1 = "... Và đây là điều quan trọng nhất, <color=#ffd34c>Tư thế của Con Người</color>!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "……即<color=#ffd34c>人的姿势</color>！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "... Das ist die <color=#ffd34c>Haltung des Menschen</color>!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "........Voici la <color=#ffd34c>posture de l'Homme</color> !"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "COUNTERCASE_INGRID_NORMAL_1@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 30921
L32_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "UNIT_SURPRISE"
L32_1.m_Face = L33_1
L32_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "무, 무슨 말인지 하나도 모르겠는데?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "な、何を言ってるのかさっぱりわからないんだけど？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I-I don’t understand a thing you're saying."
L32_1.m_Talk_ENG = L33_1
L33_1 = "你在說什麼我有聽沒有懂？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ฉันไม่เข้าใจสิ่งที่คุณพูด"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tôi không hiểu gì cả."
L32_1.m_Talk_VTN = L33_1
L33_1 = "嗯？我、我完全听不懂？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "I-ich habe keine Ahnung, wovon du redest!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Je....je ne comprends rien du tout à ce que tu racontes !"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "COUNTERCASE_INGRID_NORMAL_1@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 30921
L33_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_LAUGH"
L33_1.m_StartBGMFileName = "CUTSCENE_AMBIENT_WIND"
L34_1 = "CHOI_ALPHA_NULL_SHORT"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L33_1.m_Crash = 40
L34_1 = "훗, 그럴만도 하지. 부동검법은 범인이 쉽게 이해할 수 있는 영역이 아니니 말이다."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ふふっ。無理もない。不動剣法は凡人に理解できる領域ではないのだから。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "I’m not surprised. Stationary Swordsmanship is not something the mediocrities can understand."
L33_1.m_Talk_ENG = L34_1
L34_1 = "呵，聽不懂也是正常的。畢竟不朽劍法可不是凡人可以輕易領悟的。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ฉันไม่แปลกใจเลย วิชาดาบที่อยู่กับที่ไม่ใช่สิ่งที่คนธรรมดาสามารถเข้าใจได้"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tôi không ngạc nhiên. Kiếm Thuật Bất Động không phải là thứ mà những người bình thường có thể hiểu được."
L33_1.m_Talk_VTN = L34_1
L34_1 = "哼，很正常。不动剑法可不是凡人能轻易理解的领域。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Hmpf, kein Wunder. Denn ein normaler Mensch kann die Stillstand-Schwertkunst nicht auf Anhieb verstehen."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Humpf, ça ne me surprend pas. Ma technique d'épée stationnaire n'est pas à la portée du premier quidam."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "COUNTERCASE_INGRID_NORMAL_1@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 30921
L34_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "CHOI_ALPHA_NULL_SHORT"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "그렇다면 두 눈으로 똑똑히 보도록."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "一度その目で確かめるがいい。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Behold for yourself."
L34_1.m_Talk_ENG = L35_1
L35_1 = "你就用眼睛看吧。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ดูเพื่อตัวคุณเอง"
L34_1.m_Talk_THA = L35_1
L35_1 = "Hãy tự xem đi."
L34_1.m_Talk_VTN = L35_1
L35_1 = "那么，睁大双眼看清楚了。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Also schau genau zu."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Tiens-toi prête."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
