L38_1 = "COUNTERCASE_INGRID_NORMAL_1@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 30921
L37_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L37_1.m_bWaitClick = true
