L38_1 = "UNIT_PRIDE"
L37_1.m_Face = L38_1
L38_1 = "CHOI_ALPHA_NULL_SHORT"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "L"
L37_1.m_Crash = 30
L38_1 = "자, 어디 동전을 몇 개 던져 보아라!"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "さあ、私にコインを何枚か投げてみろ！"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Now, throw me a couple of coins!"
L37_1.m_Talk_ENG = L38_1
L38_1 = "你試試扔幾個硬幣！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เอาล่ะ โยนเหรียญมาให้ฉันสักสองสามเหรียญ!"
L37_1.m_Talk_THA = L38_1
L38_1 = "Giờ hãy ném cho tôi vài đồng xu!"
L37_1.m_Talk_VTN = L38_1
L38_1 = "来，扔几个硬币！"
L37_1.m_Talk_SCN = L38_1
L38_1 = "So, wirf ein paar Münzen auf den Boden!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Bon, maintenant jette-moi quelques pièces !"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "COUNTERCASE_INGRID_NORMAL_1@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 30921
L38_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L38_1.m_Pos = "R"
L39_1 = "동전? 그러고보니, 마침 거스름 돈이 주머니에……."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "コイン？　それなら、ちょうどおつりの小銭がポケットに……"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Coins? Oh, I have some change in my pocket..."
L38_1.m_Talk_ENG = L39_1
L39_1 = "硬幣？我口袋裡剛好有找的零錢……"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เหรียญ? โอ้ ฉันมีเงินทอนอยู่ในกระเป๋า..."
L38_1.m_Talk_THA = L39_1
L39_1 = "Đồng xu? À, tôi có ít tiền lẻ trong túi..."
L38_1.m_Talk_VTN = L39_1
L39_1 = "硬币？正好，兜里有些硬币……"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Münzen? Ich habe zufällig Kleingeld in der Tasche ..."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Des pièces ? Oh, je dois avoir un peu de monnaie dans mes poches..."
L38_1.m_Talk_FRA = L39_1
