L46_1 = "대, 대단해! 제자리에서 한 발짝도 움직이지 않고 그 많은 동전을 다 잡았다고?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "す、すごい！　一歩も動かずにコインを全部キャッチした！？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Y-you’re great! You caught all the coins without moving your feet!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "好…好厲害！！竟然可以單腳站立接硬幣，而且腳完全沒有動欸！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ค-คุณเยี่ยมมาก! คุณจับเหรียญทั้งหมดได้โดยไม่ต้องขยับเท้า!"
L45_1.m_Talk_THA = L46_1
L46_1 = "A- thật tuyệt vời! Cậu đã bắt được tất cả các đồng xu mà không cần di chuyển đôi chân của mình!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "好、好厉害！在原地不动的状态下，一下子抓住了那么多硬币？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "W-Wahnsinn! Du hast alle Münzen gefangen, ohne dich auch nur einen Schritt zu bewegen?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "I....incroyable ! Tu n'as pas bougé d'un centimètre et tu as réussi à attraper toutes ces pièces ?!"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "COUNTERCASE_INGRID_NORMAL_1@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 30921
