L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L46_1.m_Pos = "C"
L47_1 = "……나, 나도 그걸 배울 수 있을까?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "……わ、私にも習得できるかな？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Will you teach me how to do that?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "我……我學得來嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "คุณจะสอนฉันถึงวิธีการทำเช่นนั้นหรือไม่?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Cậu sẽ dạy tôi cách làm chứ?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "……我、我也能学习这个吗？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "... K-könnte ich das auch lernen?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Est-ce que.... Tu pourrais m'apprendre ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "COUNTERCASE_INGRID_NORMAL_1@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 30921
L47_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "UNIT_PRIDE"
L47_1.m_Face = L48_1
L48_1 = "CHOI_ALPHA_NULL_SHORT"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L47_1.m_Crash = 40
L48_1 = "물론이지! 부동검법은 오롯이 내가 창시한 검법."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "もちろん！　不動剣法は私が創始した剣法である。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Of course! Stationary Swordsmanship is my own creation."
L47_1.m_Talk_ENG = L48_1
L48_1 = "那當然！不朽劍法是我獨創的劍法。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "แน่นอน! วิชาดาบที่อยู่กับที่คือสิ่งที่ฉันสร้างขึ้นเอง"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tất nhiên rồi! Kiếm Thuật Bất Động là sáng tạo của riêng tôi."
L47_1.m_Talk_VTN = L48_1
L48_1 = "当然！不动剑法是我自创的剑法。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Natürlich! Die Stillstand-Schwertkunst ist meine ureigene Kreation."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Bien sûr ! Après tout, c'est moi qui ai créé cette technique d'épée stationnaire."
L47_1.m_Talk_FRA = L48_1
