L50_1.m_Face = "UNIT_IDLE"
L51_1 = "CHOI_ALPHA_NULL_SHORT"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "L"
L51_1 = "세상의 균형을 위해 싸울 것이라 약속한다면, 내 기꺼이 이름과 기술을 전수해주마."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "世界の均衡のために戦うと約束するのであれば、\n私は喜んでその名と技術を伝授しよう。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Promise me that you will fight for the balance of the world, and I will teach you my name and my swordsmanship."
L50_1.m_Talk_ENG = L51_1
L51_1 = "只要你答應我，你會為世界的平衡而戰，那我就將我辛苦發明的劍法傳授給你！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "สัญญากับฉันว่าคุณจะต่อสู้เพื่อความสมดุลของโลก และฉันจะสอนชื่อของฉันและทักษะดาบของฉันแก่คุณ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Hãy hứa với tôi rằng cô sẽ chiến đấu vì sự cân bằng của thế giới và tôi sẽ dạy cho cô tên cũng như kiếm thuật của tôi."
L50_1.m_Talk_VTN = L51_1
L51_1 = "如果你能发誓，会为了世界的平衡而战，我可以传授给你。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Versprichst du mir, dass du der Balance der Welt zuliebe kämpfen wirst, so werde ich dir gerne den Namen übertragen und die Technik lehren."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Promets-moi seulement que tu te battras pour maintenir l'équilibre du monde et je t'enseignerai mon nom et mon art."
L50_1.m_Talk_FRA = L51_1
