L3_1.m_Face = L4_1
L3_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L3_1.m_Pos = "C"
L4_1 = "어, 그런데 내 동전은 안 돌려주는 거야?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "ところで、私の小銭は返してくれないの？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Um, by the way, are you going to give me my coins back?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "不過，剛扔的那些零錢你不還給我嗎？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เอ่อ คุณจะเอาเหรียญของฉันคืนมาให้ฉันเหรอ?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Ừm, mà cậu có định trả lại tiền cho tôi không?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "呃，不过硬币不还给我吗？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Huch, aber kriege ich meine Münzen nicht wieder?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Euh, mais... Tu ne vas pas me rendre ma monnaie ?"
L3_1.m_Talk_FRA = L4_1
