L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "부동검법을 이해하고 싶다면 물질적인 욕구에 집착하지 말도록."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "不動剣法を理解するためには、物質への欲に執着しないように。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "If you want to learn Stationary Swordsmanship, you must rid yourself of materialistic desires."
L5_1.m_Talk_ENG = L6_1
L6_1 = "要想明白不朽劍法的真諦，就不能執著於物質的享受。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "หากคุณต้องการเรียนรู้วิชาดาบแบบอยู่กับที่ คุณต้องกำจัดความปรารถนาทางวัตถุ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Nếu muốn học Kiếm Thuật Bất Động, cô phải thoát khỏi ham muốn vật chất."
L5_1.m_Talk_VTN = L6_1
L6_1 = "如果想理解不动剑法的奥义的话，就要放弃物质的欲望。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Willst du die Stillstand-Schwertkunst verstehen, so verliere dein Herz nicht an materielle Triebe."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Si tu veux maîtriser ma technique d'épée stationnaire, tu dois d'abord apprendre à te détacher des biens matériels."
L5_1.m_Talk_FRA = L6_1
