L31_1 = "ฉันประทับใจมากที่คุณติดตามฉันมาไกลขนาดนี้"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi rất ấn tượng vì cô theo kịp tôi cho đến nay."
L30_1.m_Talk_VTN = L31_1
L31_1 = "……能坚持训练到这里，真是了不起。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "... Beeindruckend, dass du das Training bis hierher befolgt hast."
L30_1.m_Talk_DEU = L31_1
L31_1 = ".... Je suis impressionné que tu aies tenu aussi longtemps."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
