L31_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L31_1.m_Pos = "C"
L31_1.m_Crash = 50
L32_1 = "최강의 마녀가 되려면 이정도는 당연하지!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "最強の魔女になるためなら、これくらい当然よ！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I want to be the strongest witch in the world. This is nothing!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "我的目標是成為最強魔女，這點訓練小意思啦！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ฉันอยากเป็นแม่มดที่แข็งแกร่งที่สุดในโลก นี่ไม่มีอะไร!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi muốn trở thành phù thủy mạnh nhất thế giới. Đây không là gì cả!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "要想成为最强的魔女，这种程度还不算什么！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Das versteht sich von selbst, wenn man die stärkste Hexe werden will!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Si je veux devenir la plus grande des sorcières, c'est la moindre des choses !"
L31_1.m_Talk_FRA = L32_1
