L35_1 = "좋은 각오군, 제자여!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "いい覚悟だ、弟子よ！"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I like your conviction, my apprentice!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "很有決心，非常好，徒弟！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ฉันชอบความเชื่อมั่นของลูกศิษย์ของฉัน!"
L34_1.m_Talk_THA = L35_1
L35_1 = "Tôi thích niềm tin của cô, đệ tử của tôi!"
L34_1.m_Talk_VTN = L35_1
L35_1 = "很好的觉悟，我的弟子！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Gute Einstellung, mein Jünger!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Quelle détermination, mon disciple !"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
