L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 30921
L35_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_StartBGMFileName = "CUTSCENE_AMBIENT_WIND"
L36_1 = "CHOI_ALPHA_NULL_SHORT"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "L"
L36_1 = "그렇다면, 조금은 이르지만 정식으로 부동검법의 계승식을 거행하도록 하지."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "では、少し早いが正式に不動剣法の継承式を執り行うことにしよう。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "If that’s the case, I will start the Stationary Swordsmanship succession ceremony now."
L35_1.m_Talk_ENG = L36_1
L36_1 = "雖然還有點早，不過就先來舉行不朽劍法的正式繼承儀式吧！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "หากเป็นเช่นนั้น ฉันจะเริ่มการสืบทอดวิชาดาบนิ่งทันที"
L35_1.m_Talk_THA = L36_1
L36_1 = "Nếu đúng như vậy, tôi sẽ bắt đầu buổi lễ kế thừa Kiếm Thuật Bất Động ngay bây giờ."
L35_1.m_Talk_VTN = L36_1
L36_1 = "这样的话，虽然还有些勉强，但可以正式举行不动剑法的继承仪式了。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Na dann, dann werde ich dir die Stillstand-Schwertkunst in einer offiziellen Nachfolger-Zeremonie übertragen."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Dans ce cas, commençons sans plus tarder la cérémonie de succession."
L35_1.m_Talk_FRA = L36_1
