L39_1 = "계승식? 그런 것도 있어?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "継承式？　そんなのがあるの？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "There is a succession ceremony?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "繼承儀式？還有這種東西？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "มีพิธีสืบทอดตำแหน่งหรอ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Có lễ kế thừa sao?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "竟然还有继承仪式？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Eine Nachfolger-Zeremonie? So was gibt es?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "La cérémonie de succession ? Ça existe vraiment ce genre de chose ?"
L38_1.m_Talk_FRA = L39_1
