L41_1 = "CHOI_ALPHA_NULL_SHORT"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L40_1.m_Crash = 30
L41_1 = "그렇다. 부동검법은 일인전승의 검법!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "そうだ、不動剣法は唯授一人の剣法！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Yes. My Stationary Swordsmanship is inherited by only one person."
L40_1.m_Talk_ENG = L41_1
L41_1 = "沒錯，這套不朽劍法只能一個人繼承！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ใช่ วิชาดาบประจำที่ของฉันสืบทอดมาจากคนเพียงคนเดียวเท่านั้น"
L40_1.m_Talk_THA = L41_1
L41_1 = "Đúng. Kiếm Thuật Bất Động của ta chỉ được thừa kế bởi một người."
L40_1.m_Talk_VTN = L41_1
L41_1 = "是的。不动剑法是单人传承的剑法！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "So ist es. Die Stillstand-Schwertkunst ist eine Kunst einer einzigen Person!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Oui. Ma technique d'épée stationnaire ne peut être détenue que par une seule personne !"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "COUNTERCASE_INGRID_NORMAL_1@191#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 30921
