L42_1 = "CHOI_ALPHA_NULL_SHORT"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L42_1 = "스승과의 대결을 통해 살아남는 쪽이 진정한 계승자가 되어 새로운 이름을 물려받게 되는 것이다!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "恩師と対決して勝ち残った者が真の継承者となり、\n新しい名が授けられるのである。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "The one who survives the duel with the master will be the true inheritor of my swordsmanship style and given a new name!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "和師父對決後，活下來的那一方就可以正式繼承劍法，也會繼承新的名字！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ผู้ที่รอดชีวิตจากการดวลกับปรมาจารย์จะเป็นผู้สืบทอดรูปแบบดาบของฉันอย่างแท้จริงและได้รับชื่อใหม่!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Người sống sót sau cuộc đấu tay đôi với sư phụ sẽ là người thừa kế thực sự phong cách kiếm thuật của ta và được đặt một cái tên mới!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "通过与师傅的对决，活下来的人将变成真正的继承者，继承新的名字！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Derjenige, der im Duell gegen seinen Meister gewinnt und überlebt, wird zum wahren Nachfolger und erbt einen neuen Namen!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Celui qui survit au duel avec le maître sera le seul et unique héritier de ma technique d'épée. Il recevra alors un nouveau nom."
L41_1.m_Talk_FRA = L42_1
