L47_1 = "UNIT_PRIDE"
L46_1.m_Face = L47_1
L47_1 = "CHOI_ALPHA_NULL_SHORT"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "L"
L47_1 = "미리 말해두자면, 그대가 받게 될 이름은… <color=#ffd34c>잉그리드 요하네스 더 헤븐즈시커</color>다."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "先に言っておくと、君が授かる名は……<color=#ffd34c>イングリッド・ヨハネス・ザ・ヘヴンズシーカー</color>である。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "For your information, your name would be... <color=#ffd34c>Ingrid Johannes the Heaven Seeker</color>."
L46_1.m_Talk_ENG = L47_1
L47_1 = "我先透露給你，你要繼承名字是… <color=#ffd34c>英格麗·約翰尼斯·天堂追尋者</color>。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ข้อมูลของคุณ ชื่อของคุณคือ... <color=#ffd34c>อิงกริด โยฮันเนส ผู้แสวงหาสวรรค์</color>"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tên của cô sẽ là... <color=#ffd34c>Ingrid Johannes the Heaven Seeker</color>."
L46_1.m_Talk_VTN = L47_1
L47_1 = "提前告诉你也无妨，你的名字就叫……<color=#ffd34c>英格丽·约翰内斯·D·海文杰斯克</color>。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ich sage es dir schon im Voraus. Dein Name wird sein ... <color=#ffd34c>Ingrid Johannes der Himmelssucher</color>."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Et ton nom à toi sera...<color=#ffd34c>Ingrid Johannes, la chercheuse du Paradis</color>."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "COUNTERCASE_INGRID_NORMAL_1@197#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
