L48_1 = "UNIT_SURPRISE"
L47_1.m_Face = L48_1
L47_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L47_1.m_Pos = "R"
L48_1 = "엥? 난 그냥 잉그리드가 좋은데?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "え？　私、名前は元のイングリッドのままがいいんだけど？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Um, I prefer just Ingrid."
L47_1.m_Talk_ENG = L48_1
L48_1 = "蛤？我想要叫英格麗就好。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "อืม ฉันชอบแค่อิงกริดมากกว่า"
L47_1.m_Talk_THA = L48_1
L48_1 = "Ừm, con thì thích Ingrid hơn."
L47_1.m_Talk_VTN = L48_1
L48_1 = "啊？可是我喜欢叫英格丽啊？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Huäh? Aber ich mag meinen Namen Ingrid, so wie er ist!"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Euh, je préfère juste Ingrid."
