L49_1 = "뭐, 어쨌든 좋아! 마침 사부와도 싸우고 싶어서 몸이 근질거리던 참이었거든!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "まあ、いっか！　師匠とは一度勝負したくてうずうずしてたんだよね！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "But okay! I really wanted to fight you, you know!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "這樣也好！我正好也想和師父過過招呢！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "แต่โอเค! ฉันอยากจะสู้กับคุณจริงๆนะรู้ไหม!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Nhưng ổn thôi! Con thực sự muốn chiến đấu với sư phụ đấy!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "总之，不重要！我正好想跟师傅切磋下来着！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Na, egal! Ich konnte es eh kaum erwarten, gegen dich zu kämpfen, Meister!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Enfin, ça ira ! Je meurs d'impatience de me battre avec toi !"
L48_1.m_Talk_FRA = L49_1
