L49_1.m_Pos = "L"
L50_1 = "후후… 좋다! 덤벼라, 제자여!"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ふふふ……よし！　かかってこい、弟子よ！"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Haha... good! Come at me, my apprentice!"
L49_1.m_Talk_ENG = L50_1
L50_1 = "呵呵…很好！出招吧，徒弟！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ฮ่าๆ...ดี! มาหาฉันสิ ลูกศิษย์ของฉัน!"
L49_1.m_Talk_THA = L50_1
L50_1 = "Haha tốt! Đến đi đệ tử!"
L49_1.m_Talk_VTN = L50_1
L50_1 = "哈哈……那好！放马过来吧，我的弟子！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Hoho ... Sehr gut! Greif an, mein Jünger!"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Ha ha... Bien ! C'est parti, ma chère élève !"
L49_1.m_Talk_FRA = L50_1
