L5_1 = "…제자여, 어째서 먼저 공격하지 않는 것이지?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "……弟子よ、なぜ攻撃してこない？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "... My apprentice, why aren’t you attacking me first?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "…徒弟，你為何不採取先攻呢？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "... ลูกศิษย์ของฉัน ทำไมไม่โจมตีฉันก่อนล่ะ?"
L4_1.m_Talk_THA = L5_1
L5_1 = "... Đệ tử, sao không tấn công ta trước?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "……我的弟子，你为什么不先攻击呢？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "... Werter Jünger, warum greifst du mich nicht zuerst an?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "... Pourquoi tu ne m'attaques pas ?"
L4_1.m_Talk_FRA = L5_1
