L6_1 = "UI_NEGOTIATE"
L5_1.m_StartBGMFileName = L6_1
L5_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L5_1.m_Pos = "R"
L6_1 = "후후후… 그동안의 훈련을 통해 깨달았거든, 사부."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ふっふっふ……これまでの訓練で気付いたの、師匠。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Hehe... I learned from your training, master."
L5_1.m_Talk_ENG = L6_1
L6_1 = "呵呵呵…這是我在訓練這段時間領悟到的，師父。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "อิอิ... ฉันเรียนรู้จากการฝึกฝนของคุณค่ะอาจารย์"
L5_1.m_Talk_THA = L6_1
L6_1 = "Hehe... Con học được từ sự huấn luyện của thầy đấy."
L5_1.m_Talk_VTN = L6_1
L6_1 = "呼呼呼……通过这段时间的训练，我领悟了一个道理，师傅。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Hohoho ... Ich habe eines begriffen im Training mit dir, Meister."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Hé hé hé... J'ai beaucoup appris de tes enseignements, maître."
L5_1.m_Talk_FRA = L6_1
