L7_1 = "COUNTERCASE_INGRID_NORMAL_1@206#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 206
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 30921
L6_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_LAUGH"
L6_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L6_1.m_Pos = "R"
L7_1 = "부동검법은 상대의 방심을 끌어내, 먼저 다가오기를 기다리는 검법이라는 걸 말이야."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "不動剣法は相手の油断を誘い、相手が攻撃を仕掛けて来るのを待つ剣法だってこと。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Stationary Swordsmanship is all about making the enemy lower their guard and attack you first."
L6_1.m_Talk_ENG = L7_1
L7_1 = "不朽劍法的精髓在於要等候敵人放下戒心率先靠近。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ทักษะการใช้ดาบแบบอยู่กับที่คือการทำให้ศัตรูลดระดับการป้องกันลงและโจมตีคุณก่อน"
L6_1.m_Talk_THA = L7_1
L7_1 = "Kiếm Thuật Bất Động là làm cho kẻ thù mất cảnh giác và tấn công mình trước."
L6_1.m_Talk_VTN = L7_1
L7_1 = "不动剑法就是引诱对方麻痹大意，让人先攻击的剑法。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Die Stillstand-Schwertkunst ist eine Kunst, bei der man das Gegenüber zur Leichtfertigkeit verleitet, sodass er zuerst näherkommt."
L6_1.m_Talk_DEU = L7_1
L7_1 = "J'ai compris que le plus important avec cette technique d'épée stationnaire, c'est de faire en sorte que l'ennemi baisse sa garde et attaque en premier."
L6_1.m_Talk_FRA = L7_1
