L10_1 = "그 짧은 시간에 부동검법의 핵심을 파악하다니. 대단하군."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "この短時間で不動剣法の本質を見抜くとは、大したものだ。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "You truly understand the essence of Stationary Swordsmanship. I’m very impressed."
L9_1.m_Talk_ENG = L10_1
L10_1 = "竟然可以在這麼短的時間內就掌握到不朽劍法的精髓，果然厲害。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "คุณเข้าใจแก่นแท้ของวิชาดาบนิ่งอย่างแท้จริง ฉันประทับใจมาก"
L9_1.m_Talk_THA = L10_1
L10_1 = "Con thực sự hiểu bản chất của Kiếm Thuật Bất Động. Ta rất ấn tượng."
L9_1.m_Talk_VTN = L10_1
L10_1 = "这么短时间就能领悟到不动剑法的核心，真是聪明。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Du hast in dieser kurzen Zeit den Kern der Stillstand-Schwertkunst begriffen. Toll."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Tu as saisi l'essentiel de ma technique en bien peu de temps. Je suis impressionné."
