L14_1 = "하지만 이런 경우를 대비하여 오의를 준비해두었지."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "だが、このような場合に備え、奥義を用意したのだ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "But I also have a special skill for this kind of scenario."
L13_1.m_Talk_ENG = L14_1
L14_1 = "但為了應付這種情況，我也有準備絕招。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "แต่ฉันมีทักษะพิเศษสำหรับสถานการณ์ประเภทนี้ด้วย"
L13_1.m_Talk_THA = L14_1
L14_1 = "Nhưng ta cũng có một kỹ năng đặc biệt cho loại tình huống này."
L13_1.m_Talk_VTN = L14_1
L14_1 = "但作为这种情况的对策，我也准备了奥义。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Aber ich habe genau für diesen Fall ein Geheimnis parat."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Mais j'ai une technique secrète pour ce genre de scénario."
L13_1.m_Talk_FRA = L14_1
