L17_1 = "오지 않겠다면, 먼저 가도록 하지, 제자여!"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "弟子よ、来ないなら私から先に仕掛けてやろう！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "If you won’t come to me, I will go to you, my apprentice!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "如果你不先出招，那我就要出招囉，徒弟！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ถ้าคุณไม่มาหาฉัน ฉันจะไปหาคุณ !"
L16_1.m_Talk_THA = L17_1
L17_1 = "Nếu con không đến thì ta sẽ tới trước."
L16_1.m_Talk_VTN = L17_1
L17_1 = "如果你不先攻击，那就接招吧，我的弟子！"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Wenn du nicht kommst, gehe ich zuerst!"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Si tu ne viens pas à moi, alors c'est moi qui irai jusqu'à toi, chère disciple !"
L16_1.m_Talk_FRA = L17_1
