L33_1 = "현장 임무가 없어서 간단한 문서 작업 좀 맡겨 놨더니, 몇날 며칠을 여기에 숨어있던 건가요?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "現場任務が無いので簡単な書類作成をお願いしましたよね？\nいつまでここに隠れているつもりですか？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "All I asked you to do was a simple documentation job, and you’ve been hiding here for days?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "因為沒有外勤工作，所以就請你處理簡單的文書工作，結果你給我躲在這裡這麼多天？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ที่ฉันขอให้คุณทำก็แค่งานเอกสารง่ายๆ แล้วคุณซ่อนอยู่ที่นี่มาหลายวันแล้วเหรอ?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tất cả những gì chị yêu cầu là một công việc ghi chép đơn giản mà em đã trốn ở đây mấy ngày rồi à?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "因为没有现场任务，所以让你在办公室工作，结果却在这里躲了这么多天？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ich habe Ihnen eine einfache Büroaufgabe gegeben, weil wir keine Einsätze vor Ort hatten. Hier haben Sie sich tagelang versteckt?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Tout ce que je t'ai demandé c'était de faire un simple travail de documentation, mais tu as préféré te cacher ici pendant des jours ?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "COUNTERCASE_INGRID_NORMAL_1@233#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 233
