L33_1.m_CutScenID = 30921
L33_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_SERIOUS"
L34_1 = "LEEJIN_ALPHA_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "R"
L33_1.m_Crash = 20
L34_1 = "문서 작성은 커녕 백업 데이터마저 날려버린 채로 도망을 쳐?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "書類作成どころか、バックアップデータまで消しておいて逃亡とは\nいい度胸ですね。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "You even deleted the backup data!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "你不只工作沒做好，把備份資料弄丟後還肇事逃逸？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "คุณยังลบข้อมูลสำรองด้วย!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Em còn xóa dữ liệu sao lưu!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "书面工作没做好就算了，把备份数据弄丢了就偷偷逃跑了吗？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Sie sind geflüchtet? Auf die Büroaufgaben haben Sie gepfiffen, und sogar die Back-Up-Daten haben Sie aus Versehen gelöscht?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Et en plus de ça, tu as supprimé toutes les données de sauvegarde ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "COUNTERCASE_INGRID_NORMAL_1@234#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 234
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 30921
L34_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_LAUGH"
L35_1 = "LEEJIN_ALPHA_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "R"
L35_1 = "따라오시죠. 이번엔 지아 아가씨가 부탁해도 절대 봐주지 않을 겁니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "来てください。今回ばかりはユイお嬢様が何と言おうと見逃しませんよ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Come with me. Even Jia won’t save you this time."
L34_1.m_Talk_ENG = L35_1
L35_1 = "跟我走。這次就算小姐為你說情，我也絕對不會輕饒你。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "มากับฉัน แม้แต่เจีย ก็ไม่สามารถช่วยคุณในครั้งนี้"
L34_1.m_Talk_THA = L35_1
L35_1 = "Đi với chị. Ngay cả Jia cũng sẽ không cứu được em lần này đâu."
L34_1.m_Talk_VTN = L35_1
L35_1 = "跟我走。这次就算是沈佳小姐为你说情，也绝不会轻饶你。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Folgen Sie mir. Diesmal drücke ich kein Auge zu, selbst wenn Fräulein Jia mich darum bittet."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Suis-moi. Cette fois-ci, Jia ne pourra pas te sauver."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "COUNTERCASE_INGRID_NORMAL_1@235#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 235
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 30921
L35_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_SERIOUS"
L36_1 = "CHOI_ALPHA_NULL_SHORT"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "L"
L36_1 = "사소한 오해가 있는 것 같군! 이건 도망이 아니라 나의 부족한 컴퓨터 지식을 단련으로 채우기 위한 명상의 일환으로서……!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "少々誤解があるようだ！　これは逃亡ではなく、私に欠如しているコンピューターの知識を鍛錬によってカバーするための瞑想の一種であり……いてっ！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "This is all a misunderstanding! I wasn’t hiding; I was only training to gain a deeper understanding of computers..."
L35_1.m_Talk_ENG = L36_1
L36_1 = "你可能對我有點小誤會！我不是肇事逃逸，我是想透過鍛鍊來補足我缺乏的電腦知識，所以才會來冥想……！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ทั้งหมดนี้เป็นความเข้าใจผิด! ฉันไม่ได้ซ่อนตัว ฉันเป็นเพียงการฝึกอบรมเพื่อให้เข้าใจคอมพิวเตอร์อย่างลึกซึ้งยิ่งขึ้น..."
L35_1.m_Talk_THA = L36_1
L36_1 = "Đây đều là hiểu lầm! Em không hề trốn tránh; Em chỉ đang tập để hiểu sâu hơn về máy tính..."
L35_1.m_Talk_VTN = L36_1
L36_1 = "你可能是对我有点小误会！我不是逃跑，而是使用冥想，来锻炼补足我的电脑知识……！"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Hier scheint ein banales Missverständnis vorzuliegen! Das ist keine Flucht, sondern Teil einer Meditation, bei der ich meine mangelnde EDV-Kenntnis per Training verbessere ...!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Tout ceci est un malentendu ! Je ne me cachais pas, j'étais seulement en train de m'entraîner afin d'approfondir mes connaissances en informatique....!"
L35_1.m_Talk_FRA = L36_1
