L44_1 = "아, 이런. 죄송합니다. 저희 직원이 실례를 범했군요."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "ああ、申し訳ございません。弊社の社員のご無礼をお許しください。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Oh, my apologies. He is our employee."
L43_1.m_Talk_ENG = L44_1
L44_1 = "真是抱歉，我們的員工失禮了。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "โอ้ ฉันขอโทษ เขาเป็นพนักงานของเรา"
L43_1.m_Talk_THA = L44_1
L44_1 = "Ồ, xin lỗi. Cậu ấy là nhân viên của chúng tôi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "啊，真是抱歉。是我的职员失礼了。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Oh je, verzeihen Sie. Ein Mitarbeiter von uns hat Ihnen Unannehmlichkeiten bereitet."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Oh, toutes mes excuses. Il semble que mon employé vous ai causé du tort."
L43_1.m_Talk_FRA = L44_1
