L45_1.m_Talk_ENG = L46_1
L46_1 = "下次要是再看到這個傢伙在公園亂晃，請打這支電話。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "กรุณาโทรหาฉันถ้าคุณเห็นเด็กคนนี้เดินไปรอบ ๆ สวนสาธารณะอีกครั้ง"
L45_1.m_Talk_THA = L46_1
L46_1 = "Hãy gọi cho tôi nếu lại thấy cậu bé này lại lang thang trong công viên nhé."
L45_1.m_Talk_VTN = L46_1
