L50_1 = "모, 모함이다! 날 도와주게, 잉그리드 요하네스 더 헤븐즈시커!"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "こ、これは罠だ！　私を助けてくれ、イングリッド・ヨハネス・ザ・ヘヴンズシーカー！"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I-it’s a set-up! Help me, Ingrid Johannes the Heaven Seeker!"
L49_1.m_Talk_ENG = L50_1
L50_1 = "這…這全是子虛烏有的事！英格麗·約翰尼斯·天堂追尋者，救我！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "มัน-มันเป็นการตั้งค่า! ช่วยฉันด้วย อิงกริด โยฮันเนส ผู้แสวงหาสวรรค์!"
L49_1.m_Talk_THA = L50_1
L50_1 = "Đ-đó là một cái bẫy! Giúp tôi với, Ingrid Johannes Người Tìm Kiếm Thiên Đường!"
L49_1.m_Talk_VTN = L50_1
L50_1 = "这、这是诬陷！救救我，英格丽·约翰内斯·D·海文杰斯克！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "E-eine Intrige ist das! Hilf mir, Ingrid Johannes der Himmelssucher!"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Je... je suis innocent ! Aide-moi Ingrid Johannes, la chercheuse du Paradis !"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
