L50_1.m_Crash = 40
L51_1 = "꾸물거리지 말고 얼른 따라와요, 가브리엘!"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "ガブリエル、ごちゃごちゃ言ってないで早く来なさい！"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Gabriel, stop playing around and follow me!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "少囉嗦，快跟我走。加布里埃爾！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "เกเบรียล หยุดล้อเล่นแล้วตามฉันมา!"
L50_1.m_Talk_THA = L51_1
L51_1 = "Gabriel, đừng đùa nữa và đi theo chị!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "别磨蹭了，快跟我走。加尔！"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Nun trödeln Sie nicht und folgen mir, Gabriel."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Arrête un peu tes bêtises et suis-moi, Gabriel !"
L50_1.m_Talk_FRA = L51_1
