L9_1.m_Pos = "C"
L9_1.m_Crash = 30
L10_1 = "흐음, 뭐 사부도 남 모를 사정이 있는 건가?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "うーん、師匠にも人知れぬ事情があるのかな？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Well, I guess the master has his own problems."
L9_1.m_Talk_ENG = L10_1
L10_1 = "嗯，難道師父也有不為人知的苦衷嗎？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ฉันเดาว่าอาจารย์คงมีปัญหาของเขาเอง"
L9_1.m_Talk_THA = L10_1
L10_1 = "Ừm, chắc là sư phụ có vấn đề riêng của mình."
L9_1.m_Talk_VTN = L10_1
L10_1 = "哼嗯，难道师傅也有不为人知的隐情吗？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Hmm. Mein Meister hat wohl Gründe, die er nicht offenlegen kann."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Hmm... J'imagine que le maître a ses propres problèmes."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "COUNTERCASE_INGRID_NORMAL_1@260#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 260
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 30921
L10_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L10_1.m_Pos = "C"
L11_1 = "그래도 오늘 하루 전혀 수확이 없는 건 아니었어."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "でも、今日一日収穫がゼロってことはなかったよね。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "But still, I learned a lot today."
L10_1.m_Talk_ENG = L11_1
L11_1 = "不過，今天一整天也不是都沒有收穫。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "แต่ถึงกระนั้นฉันก็ได้เรียนรู้มากมายในวันนี้"
L10_1.m_Talk_THA = L11_1
L11_1 = "Nhưng hôm nay mình vẫn học được rất nhiều điều."
L10_1.m_Talk_VTN = L11_1
L11_1 = "不过，今天一天也不是没有收获。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Trotzdem war der Tag nicht für die Katz."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Mais cette journée n'aura pas été vaine."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "COUNTERCASE_INGRID_NORMAL_1@261#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 261
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 30921
L11_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_1"
L11_1.m_bWaitClick = true
