L11_1.m_Face = "UNIT_SERIOUS"
L11_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L11_1.m_Pos = "C"
L11_1.m_Crash = 50
L12_1 = "…읏차! 이제 돌아가자, 그리고 다시 한번 라우라한테 도전하는 거야!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "……さて！　今日はもう帰ろう。それでラウラに再挑戦するんだ！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Let’s go back now! And I’ll challenge Laura once again!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "…嘿咻！差不多該回去了。我要再向蘿拉發起挑戰！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "กลับกันเถอะ! และฉันจะท้าทายลอร่าอีกครั้ง!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Quay lại thôi! Và tôi sẽ thách thức Laura một lần nữa!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "……嘿咻！现在该回去了。然后再次向劳拉发起挑战！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "... Hepp! Jetzt gehe ich zurück. Und fordere Laura noch einmal heraus!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "... Bon ! Il est temps d'y aller. Je vais essayer de battre Laura encore une fois !"
L11_1.m_Talk_FRA = L12_1
